package com.bank.image.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Flips each row horizontally and inverts each bit, fused in one pass.
public class ImageService {
    private static final Logger log = Logger.getLogger(ImageService.class.getName());

    public int[][] flipAndInvert(int[][] image) {
        for (int[] row : image) {
            int lo = 0, hi = row.length - 1;
            while (lo < hi) {
                int leftInverted = row[lo] ^ 1;  // invert left value
                row[lo] = row[hi] ^ 1;           // bring inverted right to left
                row[hi] = leftInverted;          // bring inverted left to right
                lo++; hi--;
            }
            if (lo == hi) row[lo] ^= 1;          // odd-length middle: invert only
            log.fine(() -> "Row transformed to " + Arrays.toString(row));
        }
        log.info("Image flipped and inverted");
        return image;
    }
}
