package com.bank.image;

import com.bank.image.service.ImageService;
import java.util.Arrays;
import java.util.logging.Logger;

public class ImageFlipApplication {
    private static final Logger log = Logger.getLogger(ImageFlipApplication.class.getName());

    public static void main(String[] args) {
        ImageService service = new ImageService();
        int[][] image = {{1, 1, 0}, {1, 0, 1}, {0, 0, 0}};
        int[][] out = service.flipAndInvert(image);
        for (int[] row : out) log.info("Result row: " + Arrays.toString(row));
    }
}
